WITH base AS (SELECT *, GREATEST(quantity, unit_price) AS greatest_quantity_unit_price FROM order_items WHERE order_id IN (10, 26, 27, 31)), summary AS (SELECT product_id, CASE WHEN greatest_quantity_unit_price >= 65 THEN 'high' WHEN greatest_quantity_unit_price >= 24 THEN 'mid' ELSE 'low' END AS greatest_quantity_unit_price_bucket, SUM(quantity) AS total_quantity, MIN(unit_price) AS min_unit_price FROM base GROUP BY product_id, CASE WHEN greatest_quantity_unit_price >= 65 THEN 'high' WHEN greatest_quantity_unit_price >= 24 THEN 'mid' ELSE 'low' END) SELECT * FROM summary ORDER BY min_unit_price DESC, product_id, greatest_quantity_unit_price_bucket LIMIT 10
